import random
from boltons.listutils import BarrelList

def make(n):
    b = BarrelList(range(n))
    # force splits into sublists
    b.lists = [list(range(0, n, 2))[:], list(range(1, n, 2))[:]]
    b.lists = [l for l in b.lists if l]
    if not b.lists:
        b.lists = [[]]
    return b

# indexing at both boundaries
for n in (0, 1, 2, 5, 10):
    b = BarrelList(range(n))
    if b.lists == [[]]:
        pass
    # force split when n>=2
    if n >= 2:
        b.lists = [list(range(n//2)), list(range(n//2, n))]
    ref = list(range(n))
    for i in range(-n-2, n+3):
        try:
            got = b[i]; be = None
        except IndexError:
            got = '<err>'
        try:
            exp = ref[i]; be = None
        except IndexError:
            exp = '<err>'
        assert got == exp, (n, i, got, exp)
print("index boundaries OK")

# insert at boundaries after split, compare to list
for n in (0, 1, 2, 5, 10):
    for idx in list(range(-n-3, n+4)) + [None]:
        b = BarrelList(range(n))
        if n >= 2 and len(b.lists) == 1:
            b.lists = [list(range(n//2)), list(range(n//2, n))]
        ref = list(range(n))
        if idx is None:
            b.insert(-10**9, 'X'); ref.insert(-10**9, 'X')
            b.insert(10**9, 'Y'); ref.insert(10**9, 'Y')
        else:
            b.insert(idx, 'X'); ref.insert(idx, 'X')
        assert list(b) == ref, (n, idx, list(b), ref)
print("insert boundaries OK")

# del slices at end
for n in (0,1,2,5,10):
    for start, stop in [(None,None),(0,None),(None,None),(2,None),(0,2),(1,1),(n, n), (n, n+5), (n-1, n)]:
        b = BarrelList(range(n))
        if n >= 2:
            b.lists = [list(range(n//2)), list(range(n//2, n))]
        ref = list(range(n))
        try:
            del b[start:stop]; e1=None
        except Exception as ex:
            e1=type(ex).__name__
        try:
            del ref[start:stop]; e2=None
        except Exception as ex:
            e2=type(ex).__name__
        assert e1==e2 and list(b)==ref, (n,start,stop,e1,e2,list(b),ref)
print("del slice OK")

# pop with empty tail sublists
b = BarrelList([1,2,3,4])
b.lists = [[1,2,3],[4],[]]
assert b.pop() == 4
assert list(b) == [1,2,3]
b.lists = [[1,2,3],[4],[],[]]
assert b.pop(1) == 2
assert list(b) == [1,3,4]
for n in (0,):
    b = BarrelList()
    try:
        b.pop(); assert False
    except IndexError:
        pass
print("pop OK")
print("ALL OK")
